import { useForm } from '@conform-to/react';

export function TasksForm() {
  const [form, fields] = useForm({ defaultValue: { tasks: [''] } });
  const tasks = fields.tasks.getFieldList();

  return <form id={form.id} onSubmit={form.onSubmit}>
    {tasks.map((task, index) => (
      <div key={task.key}>
        <input name={task.name} />
        <button type="submit" {...form.remove.getButtonProps({
          name: fields.tasks.name, index,
        })}>Delete</button>
        <button type="submit" {...form.reorder.getButtonProps({
          name: fields.tasks.name, from: index, to: 0,
        })}>Top</button>
      </div>
    ))}
    <button type="submit" {...form.insert.getButtonProps({
      name: fields.tasks.name,
    })}>Add task</button>
  </form>;
}

